/// Looks up the C# constant name for an opcode in one of the [`NAMES`](cs::NAMES) tables.
pub fn name_of(table: &[(u16, &'static str)], opcode: u16) -> Option<&'static str> {
    table.iter().find(|(op, _)| *op == opcode).map(|(_, n)| *n)
}
